CHS.append(CH(
 "Saving your work: tape and disk",
 ("Storage", []),
 ["When you switch a C64 off, memory is wiped. To keep programs you save them to cassette tape or floppy disk, and LOAD them back later.",
  "Each storage device has a number: 1 for tape, 8 for the first disk drive. Disks have a directory you can list.",
  "This last chapter explains the commands, the file types and how emulators store tapes and disks as files today."],
 [("Datassette", "Commodore's cassette tape drive, device 1."),
  ("1541", "Commodore's floppy disk drive, usually device 8."),
  ("Directory", "The list of files on a disk, loaded with LOAD \"$\",8."),
  ("Block", "254 bytes of a file on disk; a 1541 disk holds 664 free blocks."),
  ("PRG / SEQ", "Program file / sequential data file."),
  ("D64 / T64 / TAP", "Files that hold a whole disk, a tape archive or a raw tape for emulators.")],
 ["SAVE \"NAME\",8 saves the BASIC program to disk; LOAD \"NAME\",8 loads it.",
  "LOAD \"$\",8 then LIST shows the disk directory (it replaces the program in memory).",
  "LOAD \"NAME\",8,1 loads machine code to the address stored in the file.",
  "Device 1 is tape, 8 the first disk drive, 4 the printer.",
  "A 1541 disk has 35 tracks; the directory lives on track 18."],
 [T("A program in memory lasts only until the power goes off. Saving copies it to a tape or disk; loading copies it back. The commands are short and take a device number after the name."),
  B("save \"mygame\",8\nload \"mygame\",8\nload \"$\",8\nlist"),
  T("LOAD \"$\",8 is a special case: it loads the disk's directory as if it were a BASIC program, and LIST then shows the file names and sizes. It replaces whatever program was in memory, so save first."),
  TB("Storage commands", ["Command", "What it does"],
     [["SAVE \"NAME\",8", "save the BASIC program to disk"], ["LOAD \"NAME\",8", "load a BASIC program from disk"], ["LOAD \"NAME\",8,1", "load to the address stored in the file (machine code)"], ["LOAD \"$\",8 then LIST", "show the directory"],
      ["LOAD \"*\",8,1", "load the first file on the disk"], ["SAVE \"NAME\" / LOAD", "the same with tape (device 1 is the default)"], ["VERIFY \"NAME\",8", "compare memory with a saved file"]]),
  TB("Device numbers", ["Number", "Device"], [["0", "keyboard"], ["1", "Datassette tape"], ["3", "screen"], ["4 and 5", "printers"], ["8 to 11", "disk drives"]]),
  T("A floppy disk is divided into rings called tracks, and each track into sectors of 256 bytes. Two bytes of each sector link to the next one, so a file block holds 254 bytes. Tape is simpler and slower: bits become pulses of different lengths, and a byte takes about a hundredth of a second. (See Figure 18.1 below.)"),
  F("c64-disk.svg", "A 1541 disk has 35 tracks with the directory on track 18. Tape stores bits as short, medium and long pulses."),
  TB("Disk and tape facts", ["", "1541 disk", "Datassette tape"],
     [["capacity", "170 KB, 664 free blocks", "depends on tape length"], ["speed", "about 400 bytes a second (faster with fast loaders)", "about 50 bytes a second"], ["random access", "yes: any file at once", "no: wind to the file"], ["emulator file", ".d64 (174848 bytes)", ".tap or .t64"]]),
  TB("File types on disk", ["Type", "Holds"], [["PRG", "a program, starting with its load address"], ["SEQ", "data written and read in order"], ["REL", "records you can read in any order"], ["USR", "special formats"], ["DEL", "a deleted or placeholder entry"]]),
  T("Today most people use emulators and modern devices that read .d64 disk images and .prg files from SD cards. A .prg file is exactly what the lab's C builds make: two bytes of load address followed by the program. The lab itself does not save to disk; copy your listings into a text file to keep them."),
  T("Where next? Type in programs from old magazines and manuals, try a C64 emulator such as VICE with disk images, read the Commodore 64 Programmer's Reference Guide, and explore the demo scene, where people still push the C64 further every year.")],
 [("What does LOAD \"$\",8 load?", ["The disk directory", "The first program", "The screen", "Nothing"], 0, "Then LIST it."),
  ("Which device number is the first disk drive?", ["8", "1", "4", "0"], 0, "Tape is 1."),
  ("What does the ,1 in LOAD \"NAME\",8,1 do?", ["Loads to the address in the file", "Loads one block", "Loads from tape", "Loads quickly"], 0, "For machine code."),
  ("Where is the directory on a 1541 disk?", ["Track 18", "Track 1", "Track 35", "Track 0"], 0, "In the middle."),
  ("What does a .prg file start with?", ["Its load address", "Its name", "A checksum", "The directory"], 0, "Two bytes, low first.")],
 [("SAVE / LOAD", "\"NAME\",8 for disk, no device for tape"), ("Directory", "LOAD \"$\",8 then LIST"), ("Devices", "1 tape, 4 printer, 8 disk"), ("1541", "35 tracks, 664 free blocks, directory on track 18")],
 [MATCH("Command and job", "Pair each command with its job.", [("LOAD \"$\",8", "load the directory"), ("SAVE \"X\",8", "save to disk"), ("LOAD \"X\",8,1", "load machine code"), ("VERIFY", "check a save")]),
  FILL("Storage", "The first disk drive is device {{8}} and tape is device {{1}}. The directory lives on track {{18}}. A disk image file ends in .{{d64}}."),
  ORDER("Save and check", "Put the steps in order.", ["Write your program", "SAVE \"NAME\",8", "VERIFY \"NAME\",8", "LOAD \"$\",8 and LIST to see it"])]))
